      sourcesContent: ["import { ChangeDetectorRef, Component, OnInit } from '@angular/core';\nimport { CommonModule } from '@angular/common';\nimport { FileService, FileResponseDTO } from '../../services/file.service';\nimport { UserService } from '../../services/user.service';\nimport { Router } from '@angular/router';\n\n@Component({\n  selector: 'app-profil',\n  standalone: true,\n  imports: [CommonModule],\n  templateUrl: './profil.html',\n  styleUrls: ['./profil.scss']\n})\nexport class ProfilComponent implements OnInit {\n  files: FileResponseDTO[] = [];\n  userEmail: string = 'Utilisateur';\n  constructor(\n    private fileService: FileService,\n    private userService: UserService,\n    private router: Router,\n    private cdr: ChangeDetectorRef \n  ) {}\n\n  ngOnInit(): void {\n    \n    this.userEmail = this.extractEmailFromToken();\n    this.loadFiles();\n  }\n  \nextractEmailFromToken(): string {\n    \n    const token = localStorage.getItem('auth_token'); \n    \n    if (token) {\n      try {\n         \n        const payload = token.split('.')[1];\n        \n         \n        const decodedPayload = JSON.parse(atob(payload));\n        \n         \n        return decodedPayload.sub || 'Utilisateur'; \n      } catch (e) {\n        console.error('Erreur lors du d\xE9codage du token', e);\n        return 'Utilisateur';\n      }\n    }\n    return 'Utilisateur';\n  }\n\n  \nloadFiles(): void {\n    this.fileService.getUserFiles().subscribe({\n      next: (data) => {\n        this.files = data;\n        this.cdr.detectChanges(); \n      },\n      error: (err) => console.error(err)\n    });\n}\n\nisMenuOpen = false;  \n\ntoggleMenu(): void {\n  this.isMenuOpen = !this.isMenuOpen;  \n}\n\n \nfilterStatus: 'ALL' | 'ACTIVE' | 'EXPIRED' = 'ALL';\n\n// Cette m\xE9thode retourne la liste filtr\xE9e\nget filteredFiles(): FileResponseDTO[] {\n  if (this.filterStatus === 'ACTIVE') {\n    return this.files.filter(f => !this.isExpired(f.expirationDate));\n  }\n  if (this.filterStatus === 'EXPIRED') {\n    return this.files.filter(f => this.isExpired(f.expirationDate));\n  }\n  return this.files; // Par d\xE9faut : 'ALL'\n}\n\n  onDelete(id: number): void {\n    if (confirm('Voulez-vous vraiment supprimer ce fichier ?')) {\n      this.fileService.deleteFile(id).subscribe(() => {\n        this.files = this.files.filter(f => f.fileId !== id);\n        this.ngOnInit();\n      });\n    }\n  }\n\n  onLogout(): void {\n    this.userService.logout();\n    this.router.navigate(['/home']);\n  }\n\n  openFile(token: string): void {\n    this.router.navigate(['/download', token]);\n  }\n\n  navigateTo(path: string): void {\n    this.router.navigate([`/${path}`]);\n  }\n\n  // --- Helpers pour l'affichage des dates ---\n\n  isExpired(dateStr: string): boolean {\n    return new Date(dateStr) < new Date();\n  }\n\n  getExpiryText(dateStr: string): string {\n    const date = new Date(dateStr);\n    if (date < new Date()) return 'Expir\xE9';\n    \n    // Calcul simple de jours restants\n    const diff = date.getTime() - new Date().getTime();\n    const days = Math.ceil(diff / (1000 * 3600 * 24));\n    return `Expire dans ${days} jour(s)`;\n  }\n\n  // --- Fonction pour d\xE9terminer l'\xE9moji selon l'extension ---\n  getFileEmoji(fileName: string): string {\n    if (!fileName) return '\uD83D\uDCC4'; // Fichier par d\xE9faut\n\n    // On r\xE9cup\xE8re l'extension en minuscules\n    const parts = fileName.split('.');\n    if (parts.length === 1) return '\uD83D\uDCC4'; // Pas d'extension trouv\xE9e\n    \n    const extension = parts.pop()?.toLowerCase();\n\n    switch (extension) {\n      // Images\n      case 'jpg':\n      case 'jpeg':\n      case 'png':\n      case 'gif':\n      case 'svg':\n      case 'webp':\n        return '\uD83D\uDDBC\uFE0F';\n      \n      // Vid\xE9os\n      case 'mp4':\n      case 'avi':\n      case 'mov':\n      case 'mkv':\n        return '\uD83C\uDFA5';\n      \n      // Audios\n      case 'mp3':\n      case 'wav':\n      case 'ogg':\n        return '\uD83C\uDFB5';\n      \n      // Documents\n      case 'pdf':\n        return '\uD83D\uDCD5';\n      case 'doc':\n      case 'docx':\n      case 'txt':\n        return '\uD83D\uDCDD';\n      case 'xls':\n      case 'xlsx':\n      case 'csv':\n        return '\uD83D\uDCCA';\n      case 'ppt':\n      case 'pptx':\n        return '\uD83D\uDCFD\uFE0F';\n      \n      // Archives\n      case 'zip':\n      case 'rar':\n      case '7z':\n      case 'tar':\n      case 'gz':\n        return '\uD83D\uDCE6';\n      \n      // Code / Dev\n      case 'html':\n      case 'css':\n      case 'js':\n      case 'ts':\n      case 'json':\n      case 'java':\n        return '\uD83D\uDC68\u200D\uD83D\uDCBB';\n\n      // Par d\xE9faut\n      default:\n        return '\uD83D\uDCC4';\n    }\n  }\n}"]
